mapper.update:
UPDATE question_record

    content = #{content},
    update_time = #{updateTime}

WHERE id = #{id}

mapper.select:
select qr.id, qr.type_id, qr.content, su.nick_name createBy, qr.create_time, qr.update_time from question_record qr left join sys_user su on qr.create_by = su.manager_num
and type_id = #{typeId} and qr.create_by = #{createBy}
order by qr.create_time desc
